import {isMobileScreen} from './mobile.js';
import {escapeHTML as esc,clamp,LETTERS,time,normalizeLayout} from './core.js';
const $=q=>document.querySelector(q);
let devices=[],tap=[];
const options=(list,value)=>list.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
export function showSettings(a){const s=a.s,m=s.mixer,lat=a.engine.latency;const outputs=[['default','システム既定'],...devices.filter(d=>d.kind==='audiooutput'&&d.deviceId!=='default').map((d,i)=>[d.deviceId,d.label||`出力 ${i+1}`])];a.modal('オーディオ・保存設定',`
 <h3>音声出力</h3><label><span>出力モード</span><select id="output-route">${options([['stereo','MASTER ステレオ'],['split','スプリット：左 MASTER / 右 CUE'],['multi','4ch：1–2 MASTER / 3–4 CUE'],['device','MASTER / CUEを別の機器へ']],m.route)}</select></label>
 <label><span>MASTER出力</span><select id="master-device">${options(outputs,m.masterSink)}</select></label><label><span>CUE出力</span><select id="cue-device">${options(outputs,m.cueSink)}</select></label>
 <div class="dialog-actions"><button data-action="apply-output" class="button primary">出力を適用</button><button data-action="list-devices" class="button">出力一覧を更新</button><button data-action="request-devices" class="button">デバイス名を取得（入力許可）</button></div>
 <p class="muted">スプリットには分岐ケーブル、4chには対応オーディオ機器が必要です。別機器のCUEは追加の遅延が生じます。音源ロードだけではCUE音はMASTERに流れません。</p>
 <label><span>ヘッドホン音量</span><input type="range" min="0" max="1" step=".01" value="${m.headphone}" data-mixer="headphone" data-map="mixer.headphone"></label><label><span>CUE ↔ MASTER</span><input type="range" min="0" max="1" step=".01" value="${m.cueMix}" data-mixer="cueMix" data-map="mixer.cueMix"></label><label><span>クロスフェーダー</span><select id="crossfader-curve">${options([['equal-power','イコールパワー'],['linear','リニア'],['cut','カット']],m.curve)}</select></label>
 <div class="note">${lat?`${lat.sampleRate.toLocaleString()} Hz · 基底 ${lat.base.toFixed(2)} ms · 出力 ${lat.output==null?'報告なし':lat.output.toFixed(2)+' ms'}`:'オーディオ開始後に遅延を表示します。'}<br>ブラウザが報告する推定値です。操作から発音までの実測値ではありません。キー固定は試験的なグラニュラー処理です。</div>
 <h3>セッションと音源</h3><p>音源・曲情報・クレート・キュー・配置・ミキサー・MIDI割当を、このブラウザの端末ストレージへ自動保存します。再開時は停止状態になります。</p><div class="dialog-actions"><button data-action="export-session" class="button">セッションJSONを書き出す</button><button data-action="import-session" class="button">セッションJSONを読み込む</button><button data-action="persist-storage" class="button">保存領域の保持をリクエスト</button><button data-action="storage-info" class="button">使用容量</button></div><p class="session-warning">JSONに音声データは含まれません。元の音源も保管してください。ブラウザデータを削除すると、この端末の音源・設定も削除されます。別の端末では同じ音源を再登録します。</p>
 <h3>ブラウザ機能</h3><table><tbody>${[['AudioWorklet',typeof AudioWorkletNode!=='undefined'],['Web MIDI','requestMIDIAccess'in navigator],['WebHID','hid'in navigator],['出力デバイス選択',!!globalThis.AudioContext?.prototype?.setSinkId],['録音',typeof MediaRecorder!=='undefined']].map(([name,yes])=>`<tr><td>${name}</td><td>${yes?'利用可能':'このブラウザでは利用不可'}</td></tr>`).join('')}</tbody></table>`);}
export function showMIDI(a){const c=a.controllers,s=a.s,inputs=c.access?[...c.access.inputs.values()]:[];a.modal('コントローラー',`<h3>MIDI Learn</h3><p>接続後にLearnを開始し、画面上の操作 → コントローラーの操作の順に選びます。MIDI Note / CC / Pitch Bendに対応します。</p><div class="dialog-actions"><button data-action="connect-midi" class="button primary">MIDIを接続</button><button data-action="toggle-learn" class="button ${c.learning?'primary':''}">${c.learning?'Learnを終了':'Learnを開始'}</button><button data-action="export-midi" class="button">マッピングを書き出す</button><button data-action="import-midi" class="button">読み込む</button></div><div class="device-list" style="margin-top:14px">${inputs.length?inputs.map(d=>`<span class="badge">${esc(d.name)} · ${d.state==='connected'?'接続':'未接続'}</span>`).join(''):'<span class="muted">接続済みMIDI入力なし</span>'}</div><div id="midi-monitor" class="midi-monitor">${esc(c.last)}</div>
 <div style="overflow:auto"><table class="mapping-table"><thead><tr><th>画面操作</th><th>入力</th><th>方式</th><th>反転</th><th></th></tr></thead><tbody>${s.midiMappings.map((m,i)=>`<tr><td class="mono">${esc(m.target)}</td><td title="${esc(m.device)}">CH${m.channel+1} ${esc(m.kind)} ${m.number}</td><td><select data-map-mode="${i}">${options([['absolute','絶対値'],['cc14','14-bit CC'],['relative-twos','相対 2の補数'],['relative-offset','相対 中央64'],['relative-sign','相対 符号']],m.mode)}</select></td><td><input type="checkbox" data-map-invert="${i}" ${m.invert?'checked':''} aria-label="${esc(m.target)}の反転"></td><td><button data-action="delete-mapping" data-index="${i}" aria-label="${esc(m.target)}の割当を削除">×</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted">まだ割り当てがありません。</td></tr>'}</tbody></table></div>
 <label><span>MIDI LED出力</span><select id="midi-output">${options([['','なし'],...(c.access?[...c.access.outputs.values()].map(d=>[d.id,d.name||d.id]):[])],s.midiOutput)}</select></label><label><input id="midi-feedback" type="checkbox" ${s.midiFeedback?'checked':''}>割当済みNoteに0 / 127でLED状態を返す</label><p>14-bit CCはMSBをCC 0〜31に割り当てます。LEDの色・液晶・モーター・機種固有のコマンドは専用プロファイルが必要です。実機ごとの動作確認は未実施です。</p>
 <details><summary>HIDプロファイル（上級）</summary><p>WebHID対応ブラウザで、機器ごとのバイト配置を指定するJSONプロファイルを使えます。メーカー独自のハンドシェイク、Feature Report、Output Reportは未実装です。HID専用機器が自動的に使えるわけではありません。</p><div class="dialog-actions"><button data-action="connect-hid" class="button">HID機器を選ぶ</button><button data-action="import-hid" class="button">HID JSONを読み込む</button><button data-action="export-hid" class="button">HID JSONを書き出す</button><button data-action="hid-template" class="button">形式サンプル</button></div><div id="hid-monitor" class="midi-monitor">${esc(c.lastHID)}</div><p>${s.hidMappings.length}件のHID割当</p></details>`);}
export function showLayouts(a){a.modal('ワークスペース',`<p>パネルの位置・サイズ・表示状態を名前付きで保存できます。音声設定や曲は現在の状態を保ちます。</p><label><span>配置の名前</span><input id="layout-name" placeholder="My booth" maxlength="100"></label><div class="dialog-actions"><button data-action="save-layout" class="button primary">現在の配置を保存</button><button data-action="edit-layout" class="button">配置を編集</button></div><h3>保存した配置</h3>${a.s.layouts.map((l,i)=>`<div class="saved-layout-row"><strong>${esc(l.name)}</strong><button data-action="restore-layout" data-index="${i}" class="button">呼び出す</button><button data-action="delete-layout" data-index="${i}" class="button">削除</button></div>`).join('')||'<p>まだ保存した配置はありません。</p>'}<h3>プリセット</h3><div class="dialog-actions"><button data-action="preset-dialog" data-preset-name="two" class="button">2デッキ</button><button data-action="preset-dialog" data-preset-name="four" class="button">4デッキ</button><button data-action="preset-dialog" data-preset-name="focus" class="button">ライブラリ重視</button></div>`);}
export function showGrid(a,i,pos){const t=a.getTrack(i);if(!t){a.toast('音源をロードしてください。');return;}tap=[];a.modal(`DECK ${LETTERS[i]} · ビートグリッド`,`<p>${esc(t.name)}</p><label><span>BPM</span><input type="number" id="grid-bpm" min="20" max="400" step=".01" value="${t.bpm}"></label><div class="dialog-actions"><button data-action="tap-bpm" class="button">TAP</button><button data-action="bpm-half" class="button">½ BPM</button><button data-action="bpm-double" class="button">×2 BPM</button></div><label><span>最初の拍（秒）</span><input type="number" id="grid-offset" min="0" max="${t.duration}" step=".001" value="${t.gridOffset||0}"></label><div class="dialog-actions"><button data-action="grid-current" data-deck="${i}" class="button">現在位置を1拍目にする</button><button data-action="grid-save" data-deck="${i}" class="button primary">グリッドを保存</button></div><p>現在位置 ${time(pos)}。解析BPMは推定値です。可変テンポの曲は一定BPMとして扱うため、途中でグリッドがずれる場合があります。</p>`);}
export function showTrackEditor(a,id){const t=a.tracks.get(id);if(!t){a.toast('ライブラリで音源を選んでください。');return;}a.modal('曲情報',`<label><span>曲名</span><input id="track-name" maxlength="500" value="${esc(t.name)}"></label><label><span>アーティスト</span><input id="track-artist" maxlength="500" value="${esc(t.artist)}"></label><label><span>BPM</span><input id="track-bpm" type="number" min="20" max="400" step=".01" value="${t.bpm}"></label><label><span>キー</span><input id="track-key" maxlength="20" value="${esc(t.key||'')}"></label><label><span>コメント</span><textarea id="track-comment" rows="3" maxlength="2000">${esc(t.comment||'')}</textarea></label><p>${esc(t.filename)} · ${time(t.duration)} · ${(t.size/1048576).toFixed(1)} MB${t.missing?' · 音源ファイル未登録':''}</p><div class="dialog-actions"><button data-action="save-track" data-track-id="${esc(id)}" class="button primary">保存</button><button data-action="download-track" data-track-id="${esc(id)}" class="button">音源を書き出す</button>${!t.demo?`<button data-action="confirm-delete-track" data-track-id="${esc(id)}" class="button danger">音源を削除</button>`:''}</div>`);}
export function showSampleEditor(a,i){const selected=isMobileScreen()?a.s.mobile.deck:a.s.selectedDeck,old=a.s.sampler[i],id=old?.trackId||a.s.decks[selected].trackId||a.s.selectedTrack,t=a.tracks.get(id),start=old?.start??(id===a.s.decks[selected].trackId?a.position(selected):0);a.modal(`サンプル ${i+1}`,`<label><span>音源</span><select id="sample-track">${options([...a.tracks.values()].map(t=>[t.id,t.name]),id)}</select></label><label><span>名前</span><input id="sample-label" maxlength="100" value="${esc(old?.label||t?.name||'Sample')}"></label><label><span>開始（秒）</span><input id="sample-start" type="number" min="0" step=".001" value="${start.toFixed(3)}"></label><label><span>長さ（秒）</span><input id="sample-duration" type="number" min=".05" max="30" step=".001" value="${(old?.duration||Math.min(8*60/(t?.bpm||120),Math.max(.05,(t?.duration||30)-start))).toFixed(3)}"></label><label><span>音量</span><input id="sample-gain" type="range" min="0" max="1" step=".01" value="${old?.gain??.8}"></label><label><input id="sample-loop" type="checkbox" ${old?.loop?'checked':''}>ループ再生（パッドを再度押すと停止）</label><div class="dialog-actions"><button data-action="save-sample" data-index="${i}" class="button primary">保存</button><button data-action="clear-sample" data-index="${i}" class="button">割当を解除</button></div><p>1パッド最大30秒。音源全体はデコード時にメモリへ読み込みます。</p>`);}
export function showLibraryMenu(a){const t=a.tracks.get(a.s.selectedTrack),crate=a.s.playlists.find(p=>p.id===a.s.playlist);a.modal('ライブラリ',`<h3>クレート</h3><p>選択中：${esc(t?.name||'なし')}</p><label><span>追加するクレート</span><select id="crate-target">${options(a.s.playlists.map(p=>[p.id,p.name]),a.s.playlist)}</select></label><div class="dialog-actions"><button data-action="add-to-crate" class="button" ${!t||!a.s.playlists.length?'disabled':''}>選択曲を追加</button>${crate?`<button data-action="remove-from-crate" class="button">選択曲をクレートから外す</button><button data-action="confirm-delete-crate" class="button danger">クレートを削除</button>`:''}</div><h3>ファイル交換</h3><div class="dialog-actions"><button data-action="exchange" class="button primary">他ソフトと読み込み / 書き出し</button><button data-action="import-folder" class="button">音源フォルダーを追加</button><button data-action="new-playlist" class="button">新しいクレート</button></div><p>rekordbox XML · Traktor NML · M3U8 · PLS · CSV · Serato crate。読み込み前に照合結果を確認できます。</p>`);}
export function showHelp(a){a.modal('SeekDeck · 使い方と対応範囲',`<p class="about-product">SeekDeck</p><p>ブラウザ上のローカルDJスタジオ。最初の2デッキにはオリジナルのデモ音源を割り当てています。▶を押すと試せます。</p><ol><li>「音源を追加」からローカル音声ファイルを取り込む。</li><li>ライブラリのA〜D、またはドラッグでデッキへロード。</li><li>基準のデッキでMASTER、もう一方でSYNCを押す。</li><li>EQ・フェーダー・パッドで演奏。RECでMASTER出力を録音。</li></ol><p>CUEは停止中に基点を設定、再生中に基点へ戻って停止します。空のホットキューは設定、登録済みはジャンプして再生。Shift＋クリックで削除。LOOP ROLLは押している間だけ反復し、離すと元の進行位置へ戻ります。</p>
 <h3>実装した機能</h3><table class="help-feature"><tbody>${[['4デッキ','ローカルPCM再生、逆再生、ジョグ／スクラッチ、SLIP、テンポ±50%'],['ミキサー','3バンドEQ・TRIM・フィルター・3種類のクロスフェーダー曲線・ピークリミッター'],['演奏','8ホットキュー／デッキ、ループ、ロール、ビートジャンプ、8サンプル'],['解析・同期','BPM／キー推定、手動グリッド、TAP、一定BPMの拍位置SYNC'],['FX・音程','Echo / Reverb / Flanger、キー固定・±12半音（グラニュラー／試験的）'],['音声出力','MASTER、スプリットCUE、4ch、別デバイスCUE（環境依存）'],['保存・整理','音源／セッションの端末保存、クレート、お気に入り、履歴、JSON、XML / NML / M3U / PLS / CSV / Serato crate'],['画面配置','移動・サイズ変更・表示切替・プリセット・名前付き保存・Undo／Redo'],['コントローラー','MIDI Learn、7/14-bit CC、3種類の相対値、Pitch Bend、Note LED、HID入力プロファイル']].map(([x,y])=>`<tr><td>${x}</td><td>${y}</td></tr>`).join('')}</tbody></table>
 <h3>未対応・未検証</h3><p>Rekordbox / Serato DJと完全同等ではありません。AIステム分離、DVSタイムコード、動画・照明、ストリーミングサービス、可変テンポグリッド、CDJ USB書き出し、各社の専用HID初期化・ディスプレイ・モーターは未実装です。すべてのコントローラーでの実機検証は行っていません。</p><p>キー固定・キーシフトは独自の簡易グラニュラー処理で、商用DSPと同等の音質ではありません。再生・SYNC・スクラッチは録音で確認してから使ってください。デコード上限は全体512 MB、取込は1ファイル300 MB・1時間までです。</p>
 <h3>キーボード</h3><table><tbody><tr><td><kbd>Space</kbd></td><td>MASTERデッキの再生／停止</td></tr><tr><td><kbd>Q</kbd> / <kbd>W</kbd></td><td>DECK A 再生／CUE</td></tr><tr><td><kbd>U</kbd> / <kbd>I</kbd></td><td>DECK B 再生／CUE</td></tr><tr><td><kbd>1</kbd>〜<kbd>4</kbd> / <kbd>6</kbd>〜<kbd>9</kbd></td><td>A / Bのホットキュー1〜4</td></tr><tr><td><kbd>Shift</kbd>＋キュー</td><td>キュー削除</td></tr><tr><td><kbd>Ctrl/⌘ Z</kbd></td><td>配置編集のUndo。ShiftでRedo。</td></tr><tr><td>ジョグにフォーカス＋<kbd>←</kbd> / <kbd>→</kbd></td><td>0.1秒シーク。Shiftで5秒。</td></tr></tbody></table>
 <h3>処理と保存</h3><p>音源はサーバーへ送信しません。Web Audio / AudioWorkletで音声処理、Workerで解析、IndexedDBで保存します。初回読み込み後はアプリとデモをオフライン用にキャッシュします。OS・ブラウザ・オーディオ機器によって遅延と対応機能が変わります。</p><p><a href="https://www.w3.org/TR/webmidi/" target="_blank" rel="noopener">Web MIDI仕様</a> · <a href="https://developer.chrome.com/docs/capabilities/hid" target="_blank" rel="noopener">WebHID公式資料</a> · <a href="https://developer.chrome.com/blog/audiocontext-setsinkid" target="_blank" rel="noopener">音声出力の公式資料</a></p>`);}
export async function handleInput(a,el){if(el.id==='crossfader-curve'){a.s.mixer.curve=el.value;a.engine.applyMixer(a.s.mixer,a.s.decks);a.save();return true;}if(el.id==='midi-output'){a.s.midiOutput=el.value;a.save();return true;}if(el.id==='midi-feedback'){a.s.midiFeedback=el.checked;a.save();return true;}if(el.hasAttribute('data-map-mode')){const m=a.s.midiMappings[Number(el.dataset.mapMode)];if(el.value==='cc14'&&(m.kind!=='cc'||m.number>31))throw new Error('14-bit CCはCC 0〜31へ割り当ててください。');m.mode=el.value;a.save();return true;}if(el.hasAttribute('data-map-invert')){a.s.midiMappings[Number(el.dataset.mapInvert)].invert=el.checked;a.save();return true;}return false;}
export async function handleAction(a,action,el){const s=a.s,i=Number(el.dataset.index);switch(action){
 case'apply-output':{await a.startAudio();const next={...s.mixer,route:$('#output-route').value,masterSink:$('#master-device').value,cueSink:$('#cue-device').value};try{await a.engine.setRoute(next);Object.assign(s.mixer,next);a.save();a.toast('音声出力を適用しました。');}catch(e){try{await a.engine.setRoute(s.mixer);}catch{}throw e;}break;}
 case'list-devices':devices=await navigator.mediaDevices.enumerateDevices();showSettings(a);break;
 case'request-devices':{const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());devices=await navigator.mediaDevices.enumerateDevices();showSettings(a);break;}
 case'persist-storage':{const ok=await navigator.storage?.persist?.();a.toast(ok?'保存領域の保持が許可されました。':'保持が許可されませんでした。音源とセッションのバックアップを保管してください。',!ok);break;}
 case'storage-info':{const info=await a.storageInfo();a.toast(info?`使用 ${(info.usage/1048576).toFixed(1)} MB / 容量目安 ${(info.quota/1073741824).toFixed(1)} GB`:'このブラウザでは容量を取得できません。');break;}
 case'export-session':a.exportJSON({format:'ORBIT DJ session',version:1,exportedAt:new Date().toISOString(),session:a.snapshot(),tracks:[...a.tracks.values()]},'SeekDeck-session.json');break;
 case'import-session':a.jsonPurpose='session';$('#json-file').click();break;
 case'connect-midi':await a.controllers.connectMIDI();showMIDI(a);break;
 case'toggle-learn':a.controllers.learning=!a.controllers.learning;document.body.classList.toggle('learning-mode',a.controllers.learning);if(a.controllers.learning){a.closeModal();a.toast('画面上の操作をクリックしてから、コントローラーを操作。MIDIからLearnを終了できます。',false,10000);}else{a.controllers.target=null;document.querySelectorAll('.learning-target').forEach(el=>el.classList.remove('learning-target'));showMIDI(a);}break;
 case'export-midi':a.exportJSON({version:1,midiMappings:s.midiMappings},'SeekDeck-MIDI.json');break;
 case'import-midi':a.jsonPurpose='midi';$('#json-file').click();break;
 case'delete-mapping':s.midiMappings.splice(i,1);a.save();showMIDI(a);break;
 case'connect-hid':await a.controllers.connectHID();showMIDI(a);break;
 case'import-hid':a.jsonPurpose='hid';$('#json-file').click();break;
 case'export-hid':a.exportJSON({version:1,hidMappings:s.hidMappings},'SeekDeck-HID.json');break;
 case'hid-template':a.exportJSON({description:'形式例。vendorId/productId/reportId/offsetは実機の仕様へ変更してください。自動検出プロファイルではありません。',version:1,hidMappings:[{vendorId:0,productId:0,reportId:0,offset:0,encoding:'uint8',mask:1,min:0,max:1,mode:'absolute',target:'deck.0.play'}]},'SeekDeck-HID-format-example.json');break;
 case'save-layout':{const name=$('#layout-name').value.trim();if(!name)throw new Error('配置の名前を入力してください。');const found=s.layouts.find(l=>l.name===name);if(found)found.layout=structuredClone(s.layout);else s.layouts.push({name,layout:structuredClone(s.layout)});a.save();showLayouts(a);break;}
 case'edit-layout':a.closeModal();if(!a.layout.editing)a.layout.toggle();break;
 case'restore-layout':a.layout.restore(s.layouts[i].layout);a.render();a.closeModal();break;
 case'delete-layout':s.layouts.splice(i,1);a.save();showLayouts(a);break;
 case'preset-dialog':a.layout.setPreset(el.dataset.presetName);a.render();a.closeModal();break;
 case'tap-bpm':{const now=performance.now();if(tap.length&&now-tap.at(-1)>2200)tap=[];tap.push(now);tap=tap.slice(-9);if(tap.length>1)$('#grid-bpm').value=(60000/((tap.at(-1)-tap[0])/(tap.length-1))).toFixed(2);break;}
 case'bpm-half':$('#grid-bpm').value=clamp(Number($('#grid-bpm').value)/2,20,400);break;
 case'bpm-double':$('#grid-bpm').value=clamp(Number($('#grid-bpm').value)*2,20,400);break;
 case'grid-current':$('#grid-offset').value=a.position(Number(el.dataset.deck)).toFixed(3);break;
 case'grid-save':{const t=a.getTrack(Number(el.dataset.deck)),bpm=Number($('#grid-bpm').value),offset=Number($('#grid-offset').value);if(!Number.isFinite(bpm)||bpm<20||bpm>400||!Number.isFinite(offset)||offset<0||offset>t.duration)throw new Error('BPMは20〜400、拍位置は曲の範囲で入力してください。');t.bpm=bpm;t.gridOffset=offset;t.bpmConfidence=100;await a.updateTrack(t);a.closeModal();break;}
 case'save-track':{const t=a.tracks.get(el.dataset.trackId),name=$('#track-name').value.trim(),bpm=Number($('#track-bpm').value);if(!name||bpm<20||bpm>400||!Number.isFinite(bpm))throw new Error('曲名と有効なBPMを入力してください。');Object.assign(t,{name,artist:$('#track-artist').value,bpm,key:$('#track-key').value,comment:$('#track-comment').value});await a.updateTrack(t);a.closeModal();break;}
 case'download-track':{const t=a.tracks.get(el.dataset.trackId);let blob=await a.getAudio(t.id);if(!blob&&t.demo){const r=await fetch(new URL(t.source,import.meta.url));if(!r.ok)throw new Error('音源を取得できません。');blob=await r.blob();}if(!blob)throw new Error('音源がありません。');a.downloadBlob(blob,t.filename||'track.wav');break;}
 case'confirm-delete-track':a.modal('音源を削除',`<p>この端末から「${esc(a.tracks.get(el.dataset.trackId)?.name)}」の音声データと曲情報を削除します。元ファイルは削除しません。</p><button data-action="delete-track" data-track-id="${esc(el.dataset.trackId)}" class="button danger">削除する</button>`);break;
 case'delete-track':await a.removeTrack(el.dataset.trackId);a.closeModal();break;
 case'save-sample':{const id=$('#sample-track').value,t=a.tracks.get(id),start=Number($('#sample-start').value),duration=Number($('#sample-duration').value);if(!t||!Number.isFinite(start)||!Number.isFinite(duration)||start<0||duration<.05||duration>30||start>=t.duration)throw new Error('開始位置と長さを曲の範囲内で指定してください。');await a.setSample(i,{trackId:id,label:$('#sample-label').value||t.name,start,duration:Math.min(duration,t.duration-start),gain:Number($('#sample-gain').value),loop:$('#sample-loop').checked});a.closeModal();break;}
 case'clear-sample':a.engine.stopSamples();await a.setSample(i,null);a.closeModal();break;
 case'create-playlist':{const name=$('#crate-name').value.trim();if(!name)throw new Error('クレート名を入力してください。');s.playlists.push({id:crypto.randomUUID(),name,tracks:[]});a.render();a.save();a.closeModal();break;}
 case'add-to-crate':{const p=s.playlists.find(p=>p.id===$('#crate-target').value);if(!p||!s.selectedTrack)throw new Error('曲とクレートを選んでください。');if(!p.tracks.includes(s.selectedTrack))p.tracks.push(s.selectedTrack);a.render();a.save();a.toast('クレートへ追加しました。');break;}
 case'remove-from-crate':{const p=s.playlists.find(p=>p.id===s.playlist);if(p)p.tracks=p.tracks.filter(id=>id!==s.selectedTrack);a.render();a.save();a.closeModal();break;}
 case'confirm-delete-crate':a.modal('クレートを削除','<p>クレートを削除します。音源はライブラリに残ります。</p><button class="button danger" data-action="delete-crate">削除する</button>');break;
 case'delete-crate':s.playlists=s.playlists.filter(p=>p.id!==s.playlist);s.playlist='all';a.render();a.save();a.closeModal();break;
 default:return false;}return true;}
